settings.custom_liquid:
{% assign c  = product.metafields.custom.color %}
{% assign f  = product.metafields.custom.fabric %}
{% assign w  = product.metafields.custom.work %}
{% assign cv = c.value | default: c %}
{% assign fv = f.value | default: f %}
{% assign wv = w.value | default: w %}

<div class="mx-final">

  <div class="mx-specs">
    <div>
      <div class="mx-label">COLOUR</div>
      <div class="mx-value">{{ cv | default: '—' }}</div>
    </div>
    <div>
      <div class="mx-label">FABRIC</div>
      <div class="mx-value">{{ fv | default: '—' }}</div>
    </div>
    <div>
      <div class="mx-label">WORK</div>
      <div class="mx-value">{{ wv | default: '—' }}</div>
    </div>
  </div>

  <hr class="mx-rule">

  <div class="mx-label">SHIPPING INFORMATION</div>
  <p class="mx-value">This product will be shipped to you in <strong>12 – 15 days</strong> from the date of order placed.</p>
</div>

<style>
  .mx-final{
    margin-top:16px;
    color:inherit;
    font-family:inherit;
  }

  /* Labels */
  .mx-final .mx-label{
    font-size:16px;
    font-weight:500;
    margin:0 0 4px 0;
    text-transform:uppercase;
    letter-spacing:.03em;
  }

  /* Values / description */
  .mx-final .mx-value{
    font-size:15px;
    font-weight:400;
    margin:0 0 10px 0;
    line-height:1.6;
  }

  /* Divider */
  .mx-final .mx-rule{
    border:0;
    border-top:1px solid #00000022;
    margin:12px 0;
    height:0;
  }

  /* Specs grid */
  .mx-final .mx-specs{
    display:grid;
    grid-template-columns:repeat(3,minmax(0,1fr));
    gap:10px 16px;
  }

  @media(max-width:749px){
    .mx-final .mx-specs{ grid-template-columns:1fr; }
  }
</style>
